from fastapi import APIRouter, HTTPException

from app import schemas
from app.repository import UserRepository

router = APIRouter()
repo = UserRepository()


@router.post("/users", response_model=schemas.UserOut, status_code=201)
def create_user(payload: schemas.UserCreate):
    return repo.add(payload.username, payload.email, payload.password)


@router.get("/users/{user_id}", response_model=schemas.UserOut)
def get_user(user_id: int):
    user = repo.get(user_id)
    if user is None:
        raise HTTPException(status_code=404, detail="user not found")
    return user


# BUG: no response_model, so the raw repository dicts (which include
# password_hash) are serialized straight to the client.
@router.get("/users")
def list_users():
    return repo.list()

