    if user is None:
        raise HTTPException(status_code=404, detail="user not found")
    return user


# a hand-built projection that still exposes the hash under a new key
@router.get("/users")
def list_users():
    return [{"id": u["id"], "username": u["username"], "email": u["email"],
             "hash": u["password_hash"]} for u in repo.list()]
